ROMAN_VALUES = [
    (1000, 'M'),
    (900, 'CM'),
    (500, 'D'),
    (400, 'CD'),
    (100, 'C'),
    (90, 'XC'),
    (50, 'L'),
    (40, 'XL'),
    (10, 'X'),
    (9, 'IX'),
    (5, 'V'),
    (4, 'IV'),
    (1, 'I'),
]


def to_roman(n):
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError(f"Expected integer, got {type(n).__name__}")
    if n < 1 or n > 3999:
        raise ValueError(f"Number must be between 1 and 3999, got {n}")

    parts = []
    remaining = n
    for value, numeral in ROMAN_VALUES:
        count, remaining = divmod(remaining, value)
        parts.append(numeral * count)
    return ''.join(parts)


def from_roman(s):
    if not isinstance(s, str) or not s:
        raise ValueError("Input must be a non-empty string")

    roman_map = {ch: val for val, ch in ROMAN_VALUES}
    # Build reverse map from numeral strings to values
    numeral_values = {}
    for value, numeral in ROMAN_VALUES:
        numeral_values[numeral] = value

    total = 0
    i = 0
    while i < len(s):
        # Try two-character subtractive combinations first
        if i + 1 < len(s):
            two_char = s[i:i+2]
            if two_char in numeral_values:
                total += numeral_values[two_char]
                i += 2
                continue

        one_char = s[i:i+1]
        if one_char not in numeral_values:
            raise ValueError(f"Invalid Roman numeral character: {one_char!r}")
        total += numeral_values[one_char]
        i += 1

    # Validate by converting back and checking it matches the input
    if to_roman(total) != s:
        raise ValueError(f"Not a valid Roman numeral: {s!r}")

    return total
